extern "C" s32 pk_mg_MenuInitResources(Ptr<dScMiniGm_c> self) {
    int i;
int j;
    Ptr<const MgEntry> tbl;
    int i2;
    int flag;
    int j2;
int j3;
    Ptr<const MgEntry> tbl2;
    volatile u16 sp0;
    volatile u16 sp2;
    Ptr<char> dst;
    Ptr<char> f;

    pk_mg_LoadTextNarcs();
    pk_mg_LoadArchive(0);
    data_0209f5f8 = 0;
    pk_mg_LoadGroup(0x27, 5);
    pk_mg_ResetFiles();

    if (!(data_0209caa0[0x48 / 4] & 0x80000000)) {
        tbl = sMiniGmRows;
        for (i = 0; i < 0x24; i++) {
            for (j = 0; j < 5; j++) {
                pk_MiniGm_SetRecord((Ptr<char>)(self), i, j, tbl->recordDefaults.v[j]);
            }
            tbl++;
        }
        data_0209caa0[0x48 / 4] |= 0x80000000;
        gMgSaveDirty = 1;
    }

    tbl2 = sMiniGmRows;
    for (i2 = 0; i2 < 0x24; i2++) {
        flag = 0;
        if (tbl2->scoreCap != 0) {
            if (tbl2->ownRecords == 1) {
                if (uword(pk_MiniGm_GetRecord((Ptr<char>)(self), i2, 0)) > uword(tbl2->scoreCap)) {
                    flag = 1;
                }
            } else {
                for (j2 = 0; j2 < 5; j2++) {
                    if (uword(pk_MiniGm_GetRecord((Ptr<char>)(self), i2, j2)) > uword(tbl2->scoreCap)) {
                        flag = 1;
                    }
                }
            }
        }
        if (flag != 0) {
            for (j3 = 0; j3 < 5; j3++) {
                pk_MiniGm_SetRecord((Ptr<char>)(self), i2, j3, tbl2->recordDefaults.v[j3]);
            }
            gMgSaveDirty = 1;
        }
        tbl2++;
    }

    if (gMgMenuPage == 1) {
        self->mSubBgScrollX = 0xb0;
    } else {
        self->mSubBgScrollX = 0;
    }
    self->mGfxSlot = 0;

    pk_mg_DisableBanks();
    *(Ptr<volatile u16>)(0x4000304) |= 0x8000;
    pk_GX_SetBankForTex(1);
    pk_GX_SetBankForBG(2);
    pk_GX_SetBankForSubBG(4);
    pk_GX_SetBankForSubOBJ(8);
    pk_GX_SetBankForOBJ(0x10);
    pk_GX_SetBankForTexPltt(0x20);

    data_0209d45c &= ~0x1f;
    data_0209d454 &= ~0x1f;
    *(Ptr<volatile u32>)(0x4000000) &= ~0x1f00;
    *(Ptr<volatile u32>)(0x4001000) &= ~0x1f00;
    pk_GX_SetGraphicsMode(1, 0, 1);
    pk_GXS_SetGraphicsMode(0);

    *(Ptr<volatile u32>)(0x4000000) &= 0xffcfffef;
    *(Ptr<volatile u32>)(0x4001000) &= 0xffcfffef;
    *(Ptr<volatile u32>)(0x4000000) &= ~0x7000000;
    *(Ptr<volatile u32>)(0x4000000) &= ~0x38000000;
    pk_GX_DispOn();
    *(Ptr<volatile u32>)(0x4001000) |= 0x10000;
    pk_mg_Fog(0, 0, 2, 0x1000);
    pk_mg_InitVram();
    *(Ptr<volatile u32>)(0x40004cc) = 0x7fff;
    *(Ptr<volatile u32>)(0x40004cc) = 0x40007fff;
    pk_mg_ResetGeometry();

    *(Ptr<volatile u16>)(0x400000c) = (*(Ptr<volatile u16>)(0x400000c) & ~3) | 1;
    *(Ptr<volatile u16>)(0x400000c) = (*(Ptr<volatile u16>)(0x400000c) & 0x43) | 0x410;
    *(Ptr<volatile u16>)(0x400000c) &= ~0x40;
    *(Ptr<volatile u32>)(0x4000018) = 0;
    pk_mg_SetBg2Offset(0, 0);

    f = pk_mg_LoadFile(0x4e);
    pk_mg_DecompressLZ16(f, pk_G2_GetBG2CharPtr());
    pk_mg_Free(f);

    f = pk_mg_LoadFile(0x58);
    pk_mg_Cache(uword(f), 0x200);
    pk_GX_LoadBGPltt((Ptr<const void>)(f), 0, 0x200);
    pk_mg_Free((Ptr<void>)(f));

    f = pk_mg_LoadFile(0x59);
    pk_mg_DecompressLZ16(f, pk_G2_GetBG2ScrPtr());
    pk_mg_Free((Ptr<void>)(f));

    if (pk_mg_Language() == 5) {
        f = pk_mg_LoadFile(0xda);
    } else if (pk_mg_Language() == 4) {
        f = pk_mg_LoadFile(0xd7);
    } else if (pk_mg_Language() == 3) {
        f = pk_mg_LoadFile(0xd6);
    } else if (pk_mg_Language() == 2) {
        f = pk_mg_LoadFile(0xd5);
    } else {
        f = pk_mg_LoadFile(0xd8);
    }
    pk_mg_DecompressLZ16(f, (Ptr<void>)(0x6400000));
    pk_mg_Free((Ptr<void>)(f));

    f = pk_mg_LoadFile(0xd9);
    pk_mg_Cache(uword(f), 0x100);
    pk_GX_LoadOBJPltt((Ptr<const void>)(f), 0, 0x100);
    pk_mg_Free((Ptr<void>)(f));

    *(Ptr<volatile u16>)(0x400100c) = (*(Ptr<volatile u16>)(0x400100c) & ~3) | 1;
    *(Ptr<volatile u16>)(0x400100c) = (*(Ptr<volatile u16>)(0x400100c) & 0x43) | 0x404;
    *(Ptr<volatile u16>)(0x400100c) &= ~0x40;
    *(Ptr<volatile u32>)(0x4001018) = 0;
    pk_mg_SetSubBg2Offset(0, 0);

    *(Ptr<volatile u16>)(0x400100e) = (*(Ptr<volatile u16>)(0x400100e) & ~3) | 3;
    *(Ptr<volatile u16>)(0x400100e) = (*(Ptr<volatile u16>)(0x400100e) & 0x43) | 0x4604;
    *(Ptr<volatile u16>)(0x400100e) &= ~0x40;
    *(Ptr<volatile u32>)(0x400101c) = self->mSubBgScrollX & 0x1ff;
    pk_mg_SetSubBg3Offset(self->mSubBgScrollX, 0);

    f = pk_mg_LoadFile(0x53);
    pk_mg_DecompressLZ16(f, pk_G2S_GetBG2CharPtr());
    pk_mg_Free((Ptr<void>)(f));

    f = pk_mg_LoadFile(0x5a);
    pk_mg_Cache(uword(f), 0x200);
    pk_GXS_LoadBGPltt((Ptr<const void>)(f), 0, 0x200);
    pk_mg_Free((Ptr<void>)(f));

    *(Ptr<volatile u16>)(0x4001008) = (*(Ptr<volatile u16>)(0x4001008) & ~3) | 2;
    *(Ptr<volatile u16>)(0x4001008) = (*(Ptr<volatile u16>)(0x4001008) & 0x43) | 0x6010;
    *(Ptr<volatile u16>)(0x4001008) &= ~0x40;
    *(Ptr<volatile u32>)(0x4001010) = self->mSubBgScrollX & 0x1ff;
    pk_mg_SetSubBg0Offset(self->mSubBgScrollX, 0);

    dst = (Ptr<char>)(pk_G2S_GetBG0CharPtr());
    sp0 = 0;
    pk_MultiStore16(sp0, dst, 0x8000);
    dst = (Ptr<char>)(pk_G2S_GetBG0ScrPtr());
    sp2 = 0x1f;
    pk_MultiStore16(sp2, dst, 0x1000);

    pk_MiniGm_LoadGroupIcons((Ptr<char>)(self));

    if (pk_mg_Language() == 5) {
        f = pk_mg_LoadFile(0xda);
    } else if (pk_mg_Language() == 4) {
        f = pk_mg_LoadFile(0xd7);
    } else if (pk_mg_Language() == 3) {
        f = pk_mg_LoadFile(0xd6);
    } else if (pk_mg_Language() == 2) {
        f = pk_mg_LoadFile(0xd5);
    } else {
        f = pk_mg_LoadFile(0xd8);
    }
    pk_mg_DecompressLZ16(f, (Ptr<void>)(0x6600000));
    pk_mg_Free((Ptr<void>)(f));

    f = pk_mg_LoadFile(0xd9);
    pk_mg_Cache(uword(f), 0x100);
    pk_GXS_LoadOBJPltt((Ptr<const void>)(f), 0, 0x100);
    pk_mg_Free((Ptr<void>)(f));

    self->mPageFlipped = 0;
    self->mArrowBobPhase = 0;
    self->mPrevPageTimer = 0;
    self->mNextPageTimer = 0;
    self->mExitTimer = 0;
    self->mIconBlinkPhase = 0;
    self->mStartLevel = 0;
    self->unk_060 = 0;
    self->unk_0a4 = 0;
    self->unk_0a8 = 0;
    self->mScrollDelay = 0;
    self->mGroupBase = gMgGroupBase;
    self->mExiting = 0;

    if (gMgSaveDirty == 1) {
        data_0209f1d8 = 1;
    }
    data_0208ee44 = 1;
    if (data_0209b2fc != 0) {
        pk_mg_SetFaders(&data_0209f61c);
    }

    data_0209b2fc = 0;
    data_0209d45c |= 0x11;
    data_0209d454 |= 0x11;
    data_0209d45c &= ~2;
    data_0209d454 &= ~2;
    data_0209d45c |= 4;
    data_0209d45c &= ~8;
    data_0209d454 |= 0xc;
    pk_mg_Music(5);
    return 1;
}
extern "C" void pk_MiniGm_LoadGroupIcons(Ptr<void> selfv) {
    Ptr<dScMiniGm_c> scene = (Ptr<dScMiniGm_c>)(selfv);
    Ptr<char> self = (Ptr<char>)(selfv);
    int i;
    int rowB;
    int j;
    int n1;
    int n2;
    int m;
    int copyLen;
    int flushSize;
    int plttSize;
    int pInit;
    int qInit;
    int resetVal;
    volatile u16 valA; /* pin pk_MultiStore16 src */
    volatile u16 valB; /* pin pk_MultiStore16 src */
    struct Off9 tbl;
    Ptr<char> f;
    int fill;
    int nbytes;
    int t;

    f = pk_mg_LoadFile(sMiniGmBgFiles[gMgGroupBase]);
    pk_mg_DecompressLZ16(f, pk_G2S_GetBG2ScrPtr());
    pk_mg_Free(f);

    f = pk_mg_LoadFile(sMiniGmBgFiles[gMgGroupBase + 4]);
    pk_mg_DecompressLZ16(f, pk_G2S_GetBG3ScrPtr());
    pk_mg_Free(f);

    i = 0;
    j = 0;
    n2 = 0;
    qInit = 0;
    n1 = 0;
    m = 0;
    pInit = 0;
    resetVal = 0;
    copyLen = 0xc0;
    flushSize = 0x200;
    t = 0x20;
    fill = 0x1f;
    nbytes = 2;
    plttSize = t;

    do {
        tbl = sMiniGmIconScreenOffsets;
        if (pk_MiniGm_IsUnlocked(self, gMgGroupBase + j) == 0) {
            int off;
            int row;
            int col;
            int destOff;
            Ptr<char> scr;

            off = tbl.v[i];
            row = n1;
            do {
                col = n2;
                destOff = off << 1;
                do {
                    Ptr<char> dstp;
                    scr = (Ptr<char>)(pk_G2S_GetBG0ScrPtr());
                    dstp = scr + destOff;
                    dstp = destOff ? dstp : dstp; /* register-dest pin; arms identical */
                    valA = (u16)(fill);
                    pk_MultiStore16(valA, dstp, nbytes);
                    destOff += 2;
                    off += 1;
                    col += 1;
                } while (col < 6);
                off += 0x1a;
                row += 1;
            } while (row < 9);
        } else {
            int row;
            int destOff;
            int idx;
            Ptr<char> ch;
            Ptr<char> scr;
            int off;
            int q;
            int p;

            f = pk_mg_LoadFile(sMiniGmIconChars[gMgGroupBase + j]);
            pk_mg_DecompressLZ16(f, (Ptr<char>)(pk_G2S_GetBG0CharPtr()) + 0x8000);
            pk_mg_Free(f);

            row = m;
            destOff = row;
            do {
                idx = scene->mGfxSlot;
                ch = (Ptr<char>)(pk_G2S_GetBG0CharPtr());
                scr = ch + (idx / 4) * 0x2400 + (idx % 4) * 0xc0 + destOff;
                ch = (Ptr<char>)(pk_G2S_GetBG0CharPtr());
                pk_MultiCopy_Int((Ptr<int>)((ch + 0x8000 + destOff)), (Ptr<int>)(scr), copyLen);
                destOff += 0x400;
            } while (++row < 9);

            f = pk_mg_LoadFile(sMiniGmIconPalettes[gMgGroupBase + j]);
            pk_mg_Cache(uword(f), flushSize);
            pk_GXS_LoadBGPltt(f, scene->mGfxSlot << 5, plttSize);
            pk_mg_Free(f);

            scene->mGfxSlots[i] = scene->mGfxSlot;

            off = tbl.v[i];
            rowB = pInit;
            p = pInit;
            do {
                q = qInit;
                destOff = off << 1;
                do {
                    Ptr<char> dstp;
                    idx = scene->mGfxSlot;
                    scr = (Ptr<char>)(pk_G2S_GetBG0ScrPtr());
                    dstp = scr + destOff;
                    dstp = idx ? dstp : dstp; /* register-dest pin; arms identical */
                    valB = (u16)(q + (p + ((idx % 4) * 6 + ((idx / 4) * 0x120 + (idx << 12)))));
                    pk_MultiStore16(valB, dstp, nbytes);
                    destOff += 2;
                    off += 1;
                    q += 1;
                } while (q < 6);
                off += 0x1a;
                p += 0x20;
